preConditionHook:
// THE MORNING LEG. At exactly firstHourBars bars into the session, measure
// the net move from the session's opening price. If it is at least minLegAtr ATRs the
// day had a strong first-hour trend leg and its direction is LATCHED for the
// rest of the session; otherwise the flag stays 0. Brooks's precondition for
// a trend-resumption day.
//
// LATCHING at a fixed bar count, rather than re-evaluating every bar, is what
// makes this a day-type flag instead of a momentum test. Momentum compares
// the close with the close N BARS ago on every bar; this compares it with the
// session open once and holds the answer.
//
// Kept apart from TrendFromOpenFlag (which only asks whether the FIRST BAR's
// extreme was taken out) and OpeningRangeVsAvgDailyRange (which only measures
// the opening range's WIDTH).
//
// A dead-flat leg gives legHeight 0, which fails the threshold at any
// minLegAtr > 0, so the branch below never has to invent a sign for zero.
//
// The ATR accumulator is advanced UNCONDITIONALLY, before the latch: it is a
// rolling accumulator and must step exactly once per bar, so it can never sit
// inside the if. Ported from AtrProfitTarget -- seeded with a full sum on the
// first calculated bar or when the length changes, thereafter TWO statements,
// because EL evaluates S[1] + in - out left to right.
//
// SESSION MODEL, per the standing decision: the twin's date > date[1],
// mirrored as day_of(ctx.Time(0)) > day_of(ctx.Time(1)); barsIn is 1 on the
// session's first bar, the corpus convention. Intraday bars only.
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    barsIn = 1;
    sessOpen = open[0];
    mld = 0;
} else {
    barsIn = barsIn + 1;
}
if (atrLen != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrv = atrSum / (int)atrLookback;
if (el_eq((double)barsIn, firstHourBars)) {
    legHeight = std::fabs(close[0] - sessOpen);
    if (el_ge(legHeight, minLegAtr * atrv)) {
        if (el_gt(close[0], sessOpen)) {
            mld = 1;
        } else {
            mld = -1;
        }
    } else {
        mld = 0;
    }
}
